Let $(A,\Delta, \varepsilon, L,\delta, \mathfrak{a})$ be a Lie-Rinehart comonoid and $(\mathcal{L}, \mathfrak{d})$ be a Lie comonoid in $\calC$. A morphism $\mathcal{J}:A\otimes \mathcal{L} \to L$ is called a cocrossed homomorphism if it satisfies

\begin{equation*}
\begin{tikzpicture}[anchorbase]
\draw[bmod] (0, 0) -- (0.25, 0.5) -- (0.25, 1)--(0,1.5);
\draw[bmod] (0.5, 0) -- (0.25, 0.5);
\draw[bmod] (0.5, 1.5) -- (0.25, 1);
\btoken{0.25, 1}{west}{\delta};
\btoken{0.25, 0.5}{west}{\mathcal{J}};
\end{tikzpicture} \ = \
\begin{tikzpicture}[anchorbase]
\draw[bmod] (0.25, 0) -- (0.25, .25) -- (0, .5)--(0,1)--(.25,1.25)--(.25,1.5);
\draw[bmod] (0.25, 0.
25) --(0.75,.75)-- (.75, 1.5);
\draw[bmod] (0.5, 0) -- (0.5, 1) -- (0.25, 1.25);
\btoken{0.25, 1.25}{east}{\mathcal{J}};
\btoken{0.25, 0.25}{east}{\mathfrak{a}};
\end{tikzpicture}\ - \
\begin{tikzpicture}[anchorbase]
\draw[bmod] (0.25, 0) -- (0.25, 0.25) -- (0, 0.5)--(0,.75)--(.5,1.25)--(.5,1.5);
\draw[bmod] (0.25, 0.25) -- (0.5, 0.5) -- (0.5, .75)--(0,1.25)--(0,1.5);
\draw[bmod] (0.75, 0) -- (0.75, 1) -- (0.5, 1.25);
\btoken{0.5, 1.25}{west}{\mathcal{J}};
\btoken{0.25, 0.25}{east}{\mathfrak{a}};
\end{tikzpicture} \ + \
\begin{tikzpicture}[anchorbase]
\draw[bmod] (0, 0) -- (0, 0.25) -- (-0.25, 0.5)--(-0.25,1)--(0,1.25)--(0,1.5);
\draw[bmod] (0, 0.25) -- (0.75,1.25)--(0.75,1.5);
\draw[bmod] (0.75, 0.25) -- (1, 0.5) -- (1, 1)--(0.75,1.25);
\draw[bmod] (0.75, 0) -- (0.75, 0.25) --(0,1.25);
\btoken{0, 1.25}{east}{\mathcal{J}};
\btoken{0.75, 1.25}{west}{\mathcal{J}};
\btoken{0, 0.25}{east}{\Delta};
\btoken{0.75, 0.25}{west}{\mathcal{D}};
\end{tikzpicture} \ .
\end{equation*}
